"""Rebuild the source-based Soulstone Survivors section without editing old metadata."""
from site_analytics import write_html
from pathlib import Path
from html import escape
import json,re
from soulstone_survivors_content import P,PAGES,S,para,table
ROOT=Path(__file__).resolve().parents[1];BASE='https://megabonk.org';A='/assets/soulstone-survivors/'
AD='<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
NAV=[('Start here',P+'beginners-guide/'),('Builds',P+'builds/'),('Co-op',P+'co-op/'),('Guides',P+'#guides')]
def ext(u,label):return f'<a href="{escape(u,quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label)} ↗<span class="sr-only"> (opens in a new tab)</span></a>'
MEDIA=json.loads((ROOT/'data/soulstone-media.json').read_text(encoding='utf8'))
def figure(key,ref=1,ru=False):
 m=MEDIA[key];stem=m['stem'];sizes=m['sizes'];w=max(sizes);h=round(m['height']*w/m['width']);caption=m['caption'];alt=m['alt']
 if ru:caption='Официальный скриншот © Game Smithing Limited. Выбор навыков; интерфейс на английском. Версия снимка не указана, проверено 2 ноября 2026. Это не тест билда.'
 return f'<figure class="game-image" data-game-image="ss-{key}"><a href="{stem}-{w}.webp" target="_blank" rel="noopener" aria-label="Open full image"><img src="{stem}-{min(sizes)}.webp" srcset="'+', '.join(f'{stem}-{n}.webp {n}w'for n in sizes)+f'" sizes="(max-width:800px) calc(100vw - 40px), 900px" width="{w}" height="{h}" alt="{escape(alt,quote=True)}" loading="eager"></a><figcaption>{caption} <a href="#source-{ref}" aria-label="Image source">[{ref}]</a> <a class="image-zoom" href="{stem}-{w}.webp" target="_blank" rel="noopener">'+('Открыть изображение ↗'if ru else'Open full image ↗')+'</a></figcaption></figure>'
def shell(route,title,desc,body,image=None,lang='en',error=False):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"'if u==route else'')+f'>{t}</a>'for t,u in NAV)
 alts=''
 if route in [P+'builds/',P+'ru/builds/']:alts=f'<link rel="alternate" hreflang="en" href="{BASE+P}builds/"><link rel="alternate" hreflang="ru" href="{BASE+P}ru/builds/">'
 og=f'<meta property="og:image" content="{BASE+MEDIA[image]["stem"]}-{max(MEDIA[image]["sizes"])}.webp">'if image else''
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{BASE+route}">{alts}{'<meta name="robots" content="noindex,follow">'if error else AD}<meta property="og:type" content="article"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{BASE+route}">{og}<link rel="icon" href="{A}favicon.ico"><link rel="apple-touch-icon" href="{A}apple-touch-icon.png"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="{A}site.css"></head><body class="ss guide-layout"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="{P}"><img src="{A}logo.svg" alt="" width="44" height="44"><span>Soulstone Survivors<small>Megabonk.org · Independent guides</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu ☰</summary><nav class="mobile-links" aria-label="Mobile navigation">{nav}</nav></details></div></header><main class="wrap" id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Megabonk.org · Independent player guides</strong><p>Not affiliated with Game Smithing Limited. Game names and artwork belong to their owners. Source-based guidance, not a playtest.</p><a href="/">Megabonk Wiki →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy">Privacy</a></nav></div></footer></body></html>'''
def article(p):
 sources=list(p['sources']);image_source='online'if p['image']=='coop'else'official'
 if image_source not in sources:sources.append(image_source)
 def refs(text):
  return re.sub(r'\{\{(\w+)\}\}',lambda m:f'<sup class="ref"><a href="#source-{sources.index(m[1])+1}" aria-label="Source {sources.index(m[1])+1}">[{sources.index(m[1])+1}]</a></sup>',text)
 ru=p.get('lang')=='ru';toc='<aside class="toc" aria-label="On this page"><strong>'+('На этой странице'if ru else'On this page')+'</strong>'+''.join(f'<a href="#{s[0]}">{s[1]}</a>'for s in p['sections'])+'<a href="#sources">'+('Источники'if ru else'Sources')+'</a></aside>'
 body=f'<nav class="crumbs" aria-label="Breadcrumb"><a href="{P}">Soulstone Survivors</a> / {p["h1"]}</nav><header class="article-head" id="guide"><span class="tag">Field guide · {p["id"]}</span><h1>{p["h1"]}</h1><div class="answer"><p>{p["answer"]}</p></div><p class="meta">'+('Редакция Megabonk.org · 2 ноября 2026 · По открытым источникам, без игрового теста'if ru else'Megabonk.org editors · Checked 2 November 2026 · Source-based; no gameplay test')+'</p></header>'+toc+'<div class="article-layout"><article class="prose">'
 for i,s in enumerate(p['sections']):
  body+=f'<section id="{s[0]}"><h2>{s[1]}</h2>'+refs(''.join(s[2:]))+'</section>'
  if i==0:body+=figure(p['image'],sources.index(image_source)+1,ru)
 body+='<section class="sources" id="sources"><h2>'+('Источники и ограничения'if ru else'Sources & verification')+'</h2><ol>'+''.join(f'<li id="source-{i}">{ext(S[k][0],S[k][1])} — {escape(S[k][2])}</li>'for i,k in enumerate(sources,1))+'</ol><p><a href="#guide">'+('К началу ↑'if ru else'Back to guide ↑')+'</a></p></section><section class="related"><h2>'+('Следующий шаг'if ru else'Choose your next step')+'</h2>'
 related=[('beginners-guide','Progression guide'),('builds','Build checklist'),('co-op','Co-op choices'),('mods','Mod loaders')]
 body+=''.join(f'<a href="{P+slug}/">{t} →</a>'for slug,t in related if slug!=p['slug'])
 if p['slug']=='builds':body+=f'<a href="{P}builds/barbarian/">Barbarian routes →</a><a href="{P}ru/builds/" lang="ru">Билды на русском →</a>'
 if p['slug']=='ru/builds':body+=f'<a href="{P}builds/" lang="en">English build guide →</a>'
 return shell(P+p['slug']+'/',p['title'],p['desc'],body+'</section></article></div>',p['image'],p.get('lang','en'))
def home():
 body=f'<section class="ss-hero" id="guide"><div><span class="tag">Independent guide · Released game</span><h1>Choose your next run.</h1><p class="ss-deck">Soulstone Survivors guides for better skill choices, permanent progress and playing with friends through fan mods.</p><p>A 3D horde-survival action roguelite by Game Smithing Limited. The base game is single-player; its unofficial co-op projects are separate installations.</p><a class="button" href="{P}beginners-guide/">Find your next upgrade →</a><a class="text-link" href="{P}co-op/">Looking for co-op?</a></div><div class="ss-cover">'+figure('combat',2)+'</div></section><div class="ss-strip"><span>01 · PLAN A BUILD</span><span>02 · CHECK YOUR UNLOCKS</span><span>03 · PICK YOUR NEXT TASK</span></div>'
 body+='<section class="section" id="guides"><span class="tag">The field index</span><h2>Start with the decision in front of you</h2><div class="ss-cards">'
 for i,p in enumerate(PAGES):body+=f'<a class="ss-card" href="{P+p["slug"]}/"'+(' lang="ru"'if p.get('lang')=='ru'else'')+f'><span class="ss-number">0{i+1}</span><h3>{p["h1"]}</h3><p>{p["answer"]}</p><span>Open guide →</span></a>'
 body+='</div></section>'
 groups=[('start','What to do first',f'<p>Spend early runs on permanent progress and one usable damage route. The <a href="{P}beginners-guide/">beginner guide</a> separates account growth from in-run decisions.</p>'),('builds','Choose a damage plan',f'<p>Use the <a href="{P}builds/">skill-chain checklist</a> before copying a loadout. For a named character, compare <a href="{P}builds/barbarian/">two reported Barbarian routes</a>. We do not claim a tested all-character tier list.</p>'),('play','Playing with friends',f'<p>The Steam product lists single-player. Fan projects provide different online and same-PC routes on Windows. <a href="{P}co-op/">Compare the co-op requirements</a> before installing a loader.</p>'),('progression','A hidden task with a fixed colour sequence',f'<p>For the winter-map circles, use <a href="{P}bumble-crystal-order/">red → blue → yellow → green → purple</a> and check where the boss dies. This is separate from ordinary map progression.</p>'),('help','When a mod guide names the wrong loader',f'<p><a href="{P}mods/">Check the author, game version and loader</a>. A MelonLoader HUD plugin is not installed by following a BepInEx co-op package guide.</p>'),('languages','Русский маршрут',f'<p lang="ru"><a href="{P}ru/builds/">Билды Soulstone Survivors: типы навыков и условия цепочек</a>. Английские названия оставлены рядом с объяснением, чтобы можно было сверить источник.</p>'),('platforms','Platform and release status','<p>Steam App 2066020 left Early Access on 17 June 2025; Early Access began 7 November 2022. Steam lists Windows, macOS and Linux. The official game website links PS5 and Xbox Series versions too. The checked official links do not list Nintendo Switch; that is not a promise that a port will never happen. Mod instructions here apply to their documented Windows versions.</p>'+ext(S['store'][0],'Steam · official product')+' <a href="#source-1">[1]</a>'),('community','Ask with enough detail','<p>Use '+ext('https://www.reddit.com/r/SoulstoneSurvivors/','Reddit · r/SoulstoneSurvivors')+' for community discussion. Include your game version, mode, weapon, skill list and what failed. This is a player community, not our support desk.</p>'),('references','Wiki and source boundaries','<p>For reference tables, visit '+ext('https://soulstone-survivors.fandom.com/wiki/Soulstone_Survivors_Wiki','Fandom · Soulstone Survivors Wiki')+'. Community data can lag behind a patch; our task pages retain the dates and limitations of their own sources. No gameplay results are claimed as ours.</p>'),('related-games','Other games on this site','<p>Soulstone Survivors is separate from <a href="/">Megabonk</a> and <a href="/azeroth-survivors/">Azeroth Survivors</a>. Their weapons, saves, developers and progression do not transfer. These are navigation links, not a ranked alternatives list.</p>')]
 body+='<div class="ss-notes">'+''.join(f'<section class="section" id="{i}"><h2>{h}</h2>{t}</section>'for i,h,t in groups)+'</div><section class="sources" id="sources"><h2>Sources & verification</h2><ol><li id="source-1">'+ext(S['store'][0],S['store'][1])+' — product checked 2 November 2026.</li><li id="source-2">'+ext(S['official'][0],S['official'][1])+' — official media and platform links; capture build unknown.</li></ol><p><a href="#guide">Back to guide ↑</a></p></section>'
 return shell(P,'Soulstone Survivors Guides: Builds, Co-op & Progress','Choose a Soulstone Survivors guide for builds, Barbarian routes, progression, co-op mods and the Bumble crystal order. Independent, source-based help.',body,'combat')
def build():
 for p in PAGES:
  f=ROOT/(P+p['slug']).lstrip('/')/'index.html';f.parent.mkdir(parents=True,exist_ok=True);write_html(f, article(p),encoding='utf8')
 write_html(ROOT/P.lstrip('/')/'index.html', home(),encoding='utf8')
 write_html(ROOT/P.lstrip('/')/'404.html', shell(P+'404','Page not found | Soulstone Survivors Guides','Find an independent Soulstone Survivors task guide.',f'<article class="legal"><h1>Page not found</h1><p>Return to the <a href="{P}">Soulstone Survivors guide index</a>.</p></article>',error=True),encoding='utf8')
 # Only idempotent body additions to existing publisher/root pages.
 f=ROOT/'index.html';t=f.read_text(encoding='utf8');marker='<div class="route-grid">'
 if 'id="soulstone-guide-entry"'not in t:
  assert marker in t;t=t.replace(marker,marker+f'<a class="route-card" id="soulstone-guide-entry" href="{P}"><span class="route-icon" aria-hidden="true">◇</span><h3>Soulstone Survivors guides</h3><p>Choose a skill-chain build, compare co-op mods and follow the winter crystal order.</p><span class="route-link">Open the independent field guide →</span></a>',1);write_html(f, t,encoding='utf8')
 f=ROOT/'privacy-policy.html';t=f.read_text(encoding='utf8')
 if 'id="soulstone-survivors-guides"'not in t:
  t=t.replace('</body>','<h2 id="soulstone-survivors-guides">Soulstone Survivors guides</h2><p>Reviewed 2 November 2026. Ordinary pages in /soulstone-survivors/ use this domain’s existing Google AdSense loader. They add no analytics tag, account form, save uploader, video embed or browser storage. External mod downloads and community links open their providers’ websites; we do not host or run their plugins. Cloudflare may add performance measurement on pages and error responses as described above. Gmail handles mail sent to our contact address.</p></body>');write_html(f, t,encoding='utf8')
 print('Built 8 ordinary pages + scoped404; reused /about/, /contact/, /privacy-policy.')
if __name__=='__main__':build()
